 def launch(a,name,thought=None):
  a.goto(args.url+'/library');a.get_by_placeholder('Search practices…').fill(name);a.get_by_role('button',name=re.compile('^'+re.escape(name))).first.click();a.wait_for_timeout(500)
  for _ in range(6):
   a.wait_for_function("""()=>document.querySelector('.urge-lovable,.tpl-frame,.scene-experience,[data-tof-stage],textarea[aria-label^=\"The thought\"]')||[...document.querySelectorAll('button')].some(b=>/^(Continue|Start |0$)/.test(b.textContent.trim()))""",timeout=20000)
   field=a.get_by_role('textbox',name=re.compile('The thought you want to'))
   if thought and field.count():field.fill(thought);click(a,'Continue');return
   if a.locator('.urge-lovable,.tpl-frame,.scene-experience,[data-tof-stage]').count():return
   zero=a.get_by_role('button',name='0',exact=True)
   if zero.count():zero.click();a.wait_for_timeout(100)
   distress=a.get_by_role('combobox',name='Current distress',exact=True)
   if distress.count():distress.select_option('0')
   next=a.get_by_role('button',name='Continue to your thought',exact=True)
   start=a.get_by_role('button',name=re.compile('^Start ')).first
   cont=a.get_by_role('button',name='Continue',exact=True)
   if next.count():next.click()
   elif start.count():start.click()
   elif cont.count():cont.click()
   else:raise AssertionError(a.locator('body').inner_text())
   a.wait_for_timeout(300)
  raise AssertionError('Host did not open '+name)
